WITH metrics AS (SELECT b.mktcode,b.tgtcode,AVG(b.volume) AS metric FROM `newzl`.`hsj_stock_hq_basic` AS b WHERE b.bizdate IN ('2026-04-14','2026-04-13','2026-04-10','2026-04-09','2026-04-08') GROUP BY b.mktcode,b.tgtcode), ranked AS (SELECT m.mktcode,m.tgtcode,m.metric,ROW_NUMBER() OVER (ORDER BY m.metric DESC,m.mktcode ASC,m.tgtcode ASC) AS rn,COUNT(*) OVER () AS population FROM metrics AS m) SELECT a.mktcode,a.tgtcode,a.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS a INNER JOIN ranked AS r ON r.mktcode=a.mktcode AND r.tgtcode=a.tgtcode WHERE a.bizdate='2026-04-14' AND r.rn<=10;
